defmodule SlaLab.Expressions.PenaltyPoints do
  @moduledoc """
  A custom query function for computing penalty points.

  Constructed programmatically with `Ash.Query.Function.new/2`.
  """

  @behaviour Ash.Query.Function

  @struct_fields [
    :arguments,
    name: :penalty_points,
    embedded?: false,
    __function__?: true,
    __predicate__?: false,
    extra: %{}
  ]

  defstruct @struct_fields

  defimpl Inspect do
    import Inspect.Algebra

    def inspect(%{arguments: args, name: name}, opts) do
      concat(
        to_string(name),
        container_doc("(", args, ")", opts, &to_doc/2, separator: ",")
      )
    end
  end

  @impl true
  def name, do: :penalty_points

  @impl true
  def args, do: [[:integer, :integer]]

  @impl true
  def returns, do: [:integer]

  @impl true
  def predicate?, do: false

  @impl true
  def private?, do: false

  @impl true
  def eager_evaluate?, do: true

  @impl true
  def evaluate_nil_inputs?, do: false

  @impl true
  def can_return_nil?(_func), do: true

  @impl true
  def new(args) do
    {:ok, struct(__MODULE__, arguments: args)}
  end

  @impl true
  def evaluate(%__MODULE__{arguments: [late_hours, weight]}) do
    cond do
      late_hours <= 0 ->
        {:known, 0}

      late_hours <= 24 ->
        {:known, late_hours * weight}

      true ->
        {:known, 24 * weight + (late_hours - 24) * weight * 2}
    end
  end

  @impl true
  def partial_evaluate(func), do: {:ok, func}
end

defmodule SlaLab.Ops.Validations.RatioWithin do
  use Ash.Resource.Validation

  alias Ash.Error.Changes.InvalidAttribute
  import Ash.Expr

  @impl true
  def init(opts) do
    max_bps = Keyword.get(opts, :max_bps)

    if is_integer(max_bps) && max_bps > 0 do
      {:ok, [max_bps: max_bps]}
    else
      {:error, "max_bps must be a positive integer"}
    end
  end

  @impl true
  def atomic(changeset, opts, _context) do
    max_bps = opts[:max_bps]

    [
      {:atomic, [:actual_hours],
       expr(
         not is_nil(^atomic_ref(:actual_hours)) and
           ratio_bps(^atomic_ref(:actual_hours), ^atomic_ref(:promised_hours)) > ^max_bps
       ),
       expr(
         error(^InvalidAttribute, %{
           field: :actual_hours,
           value: ^atomic_ref(:actual_hours),
           message: "delivery ratio exceeds the allowed maximum"
         })
       )}
    ]
  end
end

